/**
 * EpistemicHierarchyBadge and TaggedOutput.
 *
 * The specification (Rev. 6, Section 21) requires every output artifact
 * generated by the platform to be tagged with which of seven evidentiary
 * categories it belongs to. These components render that tag.
 *
 * The seven category definitions live in ./epistemic.ts. This file
 * exports only React components, which is what the Fast Refresh plugin
 * requires.
 */

import type { CSSProperties, ReactNode } from "react"
import {
  BAND_COLOR_VAR,
  EPISTEMIC_TAGS,
  type EpistemicTag,
} from "./epistemic"

export type EpistemicBadgeProps = {
  tag: EpistemicTag
  className?: string
}

export function EpistemicBadge({ tag, className }: EpistemicBadgeProps) {
  const info = EPISTEMIC_TAGS[tag]
  const classes = ["epistemic-badge", className].filter(Boolean).join(" ")
  const style = {
    "--epistemic-band-color": BAND_COLOR_VAR[info.band],
  } as CSSProperties
  return (
    <span
      className={classes}
      data-epistemic-tag={tag}
      data-epistemic-band={info.band}
      data-epistemic-level={info.level}
      style={style}
    >
      <span className="epistemic-badge__dot" aria-hidden="true" />
      <span className="epistemic-badge__level" aria-hidden="true">
        {info.level}
      </span>
      <span className="epistemic-badge__label">{info.label}</span>
    </span>
  )
}

export type TaggedOutputProps = {
  tag: EpistemicTag
  children: ReactNode
  className?: string
}

/**
 * TaggedOutput wraps any output artifact with its Section 21 epistemic
 * badge. Features must use this component rather than rendering raw
 * content, so the tagging is structurally required rather than a
 * convention.
 */
export function TaggedOutput({ tag, children, className }: TaggedOutputProps) {
  const classes = ["tagged-output", className].filter(Boolean).join(" ")
  return (
    <div className={classes} data-tagged-output>
      <EpistemicBadge tag={tag} />
      <div className="tagged-output__content">{children}</div>
    </div>
  )
}
